import XCTest
@testable import ColorComposerCore

/// Replays the committed solver parity corpus against
/// `WeightedSquaredErrorScorer` and `CompositionSolver`.
///
/// The corpus is generated by the Elixir service (viamin/color_matching,
/// `priv/parity/v1/corpus.json`, see `docs/solver-parity-corpus.md`) as the
/// shared source of truth for client/server solver parity. Every scenario
/// pins, per candidate: the exact weighted squared-error score or exclusion,
/// and the earliest-index-wins selection including tie evidence. Any silent
/// divergence — tie-breaking, missing-measurement exclusion, or channel
/// weighting — fails here.
///
/// The fixture is loaded from `Tests/Fixtures` (relative to this source file)
/// rather than a bundle resource so it stays byte-identical to upstream.
final class SolverParityCorpusTests: XCTestCase {
    private enum ParityHarnessError: Error, CustomStringConvertible {
        case invalidHex(String)

        var description: String {
            switch self {
            case .invalidHex(let hex): return "Corpus entry carries an unparseable hex color: \(hex)"
            }
        }
    }

    // MARK: - Corpus JSON mirror (wire format of priv/parity/v1/corpus.json)

    private struct Corpus: Codable {
        let algorithmVersion: Int
        let scorer: String
        let selection: String
        let missingPolicy: String
        let lightSources: [String]
        let scenarios: [Scenario]

        enum CodingKeys: String, CodingKey {
            case algorithmVersion = "algorithm_version"
            case scorer
            case selection
            case missingPolicy = "missing_policy"
            case lightSources = "light_sources"
            case scenarios
        }
    }

    private struct Scenario: Codable {
        let id: String
        let description: String
        let weights: [String: Double]
        let target: Entry
        let palette: [Entry]
        let expected: Expected
    }

    private struct Entry: Codable {
        let index: Int?
        let hexColor: String
        /// Measured normalized brightness per light source; a channel absent
        /// from this map is *missing* (never "measured as zero").
        let channels: [String: Double]

        enum CodingKeys: String, CodingKey {
            case index
            case hexColor = "hex_color"
            case channels
        }
    }

    private struct Expected: Codable {
        let scores: [ExpectedScore]
        let selectedIndex: Int?
        let selectedHexColor: String?
        let error: Double?
        let tieBroke: Bool?
        let tiedIndices: [Int]

        enum CodingKeys: String, CodingKey {
            case scores
            case selectedIndex = "selected_index"
            case selectedHexColor = "selected_hex_color"
            case error
            case tieBroke = "tie_broke"
            case tiedIndices = "tied_indices"
        }
    }

    private struct ExpectedScore: Codable {
        let index: Int
        let value: ScoreValue

        enum CodingKeys: String, CodingKey {
            case index
            case value = "score"
        }
    }

    /// The corpus encodes a per-candidate outcome as either a finite number
    /// or the literal string `"excluded"` — mirroring `ScorerResult`.
    private enum ScoreValue: Equatable, Decodable {
        case score(Double)
        case excluded

        init(from decoder: Decoder) throws {
            let container = try decoder.singleValueContainer()
            if let value = try? container.decode(Double.self) {
                self = .score(value)
            } else if let marker = try? container.decode(String.self), marker == "excluded" {
                self = .excluded
            } else {
                throw DecodingError.dataCorruptedError(
                    in: container,
                    debugDescription: "score must be a number or the string \"excluded\""
                )
            }
        }
    }

    // MARK: - Fixture loading

    private static let corpus: Corpus = loadCorpus()

    private static func loadCorpus() -> Corpus {
        let fixtureURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()   // .../Tests/ColorComposerCoreTests
            .deletingLastPathComponent()   // .../Tests
            .appendingPathComponent("Fixtures/parity-corpus-v1.json")
        do {
            return try JSONDecoder().decode(Corpus.self, from: Data(contentsOf: fixtureURL))
        } catch {
            fatalError("Failed to load solver parity corpus at \(fixtureURL): \(error)")
        }
    }

    /// Scenario IDs the corpus must always cover: ties, missing-measurement
    /// exclusion (candidate, target, all-excluded), zero-weight and unknown
    /// weight sources, exact matches, and a large mixed palette. Upstream may
    /// append scenarios; removing any of these weakens parity and must fail.
    private static let requiredScenarioIDs: Set<String> = [
        "distinct-errors",
        "tie-symmetric-around-target",
        "tie-duplicate-vectors",
        "tie-three-way-on-lps",
        "missing-candidate-excluded",
        "missing-target-excluded",
        "zero-weight-channel-missing",
        "all-excluded",
        "single-channel-lps",
        "exact-match-zero-error",
        "unknown-weight-ignored",
        "mixed-large-palette",
    ]

    // MARK: - Corpus metadata

    func testCorpusMetadataMatchesPinnedSemantics() {
        let corpus = Self.corpus
        XCTAssertEqual(corpus.algorithmVersion, 1, "algorithm_version bump means every expectation moved; update the corpus fixture and this pin together")
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.lightSources, LightingCondition.all.map(\.rawValue), "corpus light sources must match LightingCondition exactly")

        let ids = Set(corpus.scenarios.map(\.id))
        XCTAssertTrue(ids.isSuperset(of: Self.requiredScenarioIDs), "corpus is missing required scenarios: \(Self.requiredScenarioIDs.subtracting(ids).sorted())")
    }

    // MARK: - Per-candidate scores (scorer parity)

    func testScorerReproducesEveryExpectedCandidateScoreExactly() throws {
        let scorer = WeightedSquaredErrorScorer()

        for scenario in Self.corpus.scenarios {
            let palette = try Self.paletteColors(from: scenario)
            let target = Self.targetVector(from: scenario.target)

            for expectedScore in scenario.expected.scores {
                let candidate = palette[expectedScore.index]
                let result = scorer.score(candidate: candidate, target: target, weights: Self.weights(from: scenario))

                switch (result, expectedScore.value) {
                case (.score(let value), .score(let expected)):
                    // Corpus values are exact binary fractions; compare exactly.
                    XCTAssertEqual(
                        value, expected, accuracy: 0,
                        "scenario \(scenario.id): candidate \(expectedScore.index) scored \(value), expected \(expected)"
                    )
                case (.excluded, .excluded):
                    break
                case let (actual, expected):
                    XCTFail("scenario \(scenario.id): candidate \(expectedScore.index) produced \(actual), expected \(expected)")
                }
            }
        }
    }

    func testExclusionOnlyAppliesToPositiveWeightChannels() throws {
        let scorer = WeightedSquaredErrorScorer()

        for scenario in Self.corpus.scenarios where scenario.id == "zero-weight-channel-missing" {
            let palette = try Self.paletteColors(from: scenario)
            let target = Self.targetVector(from: scenario.target)
            let weights = Self.weights(from: scenario)

            // blue carries zero weight: the candidate missing blue and the
            // candidate with wildly different blue must both be rankable and
            // tie exactly — missing data on unweighted channels neither
            // excludes nor contributes.
            for expectedScore in scenario.expected.scores {
                guard case .score(let value) = expectedScore.value else {
                    XCTFail("scenario \(scenario.id): candidate \(expectedScore.index) must be rankable, not excluded")
                    continue
                }
                guard case .score(let actual) = scorer.score(candidate: palette[expectedScore.index], target: target, weights: weights) else {
                    XCTFail("scenario \(scenario.id): candidate \(expectedScore.index) must not be excluded")
                    continue
                }
                XCTAssertEqual(actual, value, accuracy: 0, "scenario \(scenario.id): candidate \(expectedScore.index)")
            }
        }
    }

    // MARK: - Selection parity (earliest index wins, ties included)

    func testSelectionMatchesExpectedOutputsIncludingTies() throws {
        let scorer = WeightedSquaredErrorScorer()

        for scenario in Self.corpus.scenarios {
            let palette = try Self.paletteColors(from: scenario)
            let target = Self.targetVector(from: scenario.target)
            let weights = Self.weights(from: scenario)

            // Replay the server's IlluminantMatching.best_match/4 policy:
            // earliest index among candidates sharing the minimum score.
            var best: (index: Int, score: Double)?
            for (index, color) in palette.enumerated() {
                guard case .score(let value) = scorer.score(candidate: color, target: target, weights: weights),
                      best.map({ value < $0.score }) ?? true else { continue }
                best = (index, value)
            }

            let expected = scenario.expected
            if let winner = best {
                XCTAssertEqual(winner.index, expected.selectedIndex, "scenario \(scenario.id): selected index")
                XCTAssertEqual(winner.score, expected.error ?? -1, accuracy: 0, "scenario \(scenario.id): winning error")
                XCTAssertEqual(palette[winner.index].hex, expected.selectedHexColor, "scenario \(scenario.id): selected hex color")

                let tied = expected.scores.compactMap { entry -> Int? in
                    guard case .score(let value) = entry.value, value == winner.score else { return nil }
                    return entry.index
                }
                XCTAssertEqual(tied, expected.tiedIndices, "scenario \(scenario.id): tied indices")
                XCTAssertEqual(expected.tieBroke, tied.count > 1, "scenario \(scenario.id): tie_broke flag")
            } else {
                XCTAssertNil(expected.selectedIndex, "scenario \(scenario.id): expected no selection")
                XCTAssertTrue(expected.tiedIndices.isEmpty, "scenario \(scenario.id): expected no tied indices")
            }
        }
    }

    func testTieScenariosSelectEarliestTiedIndex() throws {
        let tieScenarios = Self.corpus.scenarios.filter { $0.expected.tieBroke == true }
        XCTAssertGreaterThanOrEqual(tieScenarios.count, 4, "corpus must keep exercising ties")

        for scenario in tieScenarios {
            guard let selectedIndex = scenario.expected.selectedIndex,
                  let firstTied = scenario.expected.tiedIndices.first
            else {
                XCTFail("scenario \(scenario.id): flagged a tie but recorded no winner")
                continue
            }
            XCTAssertEqual(
                selectedIndex, firstTied,
                "scenario \(scenario.id): earliest-index-wins must pick the first tied candidate"
            )
        }
    }

    // MARK: - Solver parity (real CompositionSolver on 1×1 grids)

    func testSolverReproducesCorpusSelectionsOnSingleCellGrids() throws {
        let solver = CompositionSolver()

        for scenario in Self.corpus.scenarios {
            let palette = try Self.paletteColors(from: scenario)
            let weights = Self.weights(from: scenario)
            let targetBrightness = Self.brightnessMap(from: scenario.target)
            let active = weights.activeEntries

            // A missing target channel with positive weight has no source
            // grid to build; that scenario is covered by the scorer tests.
            let buildable = active.allSatisfy { targetBrightness[$0.condition] != nil }
            if !buildable {
                XCTAssertEqual(scenario.id, "missing-target-excluded", "only the missing-target scenario should lack a buildable source grid")
                continue
            }

            let grids = Dictionary(
                uniqueKeysWithValues: active.compactMap { condition, _ in
                    targetBrightness[condition].map { ($0, BrightnessGrid(width: 1, height: 1, values: [$0])) }
                }
            )
            let result = try solver.solve(palette: palette, sourceGrids: grids, weights: weights)

            let expected = scenario.expected
            if let selectedIndex = expected.selectedIndex {
                XCTAssertEqual(result.colorIndex(x: 0, y: 0), selectedIndex, "scenario \(scenario.id): solver selection")
                XCTAssertEqual(result.error(x: 0, y: 0), expected.error ?? -1, accuracy: 0, "scenario \(scenario.id): solver error")
                if let index = result.colorIndex(x: 0, y: 0) {
                    XCTAssertEqual(palette[index].hex, expected.selectedHexColor, "scenario \(scenario.id): solver selected hex color")
                }
            } else {
                XCTAssertNil(result.colorIndex(x: 0, y: 0), "scenario \(scenario.id): expected an unmatched cell")
                XCTAssertTrue(result.errors[0].isInfinite, "scenario \(scenario.id): unmatched cells must carry infinite error")
            }

            let expectedExcluded = palette.filter { color in
                active.contains { color.brightness(for: $0.condition) == nil }
            }.count
            XCTAssertEqual(
                result.excludedCandidateCount, expectedExcluded,
                "scenario \(scenario.id): excluded-candidate diagnostics"
            )
        }
    }

    // MARK: - Corpus → domain mapping

    /// Unknown light sources in the weights map (e.g. "ultraviolet") are
    /// dropped, exactly as the app cannot represent them — mirroring the
    /// server ignoring measurements it has no light source for.
    private static func weights(from scenario: Scenario) -> ChannelWeights {
        ChannelWeights(
            white: scenario.weights["white"] ?? 0,
            red: scenario.weights["red"] ?? 0,
            green: scenario.weights["green"] ?? 0,
            blue: scenario.weights["blue"] ?? 0,
            lps: scenario.weights["lps"] ?? 0
        )
    }

    private static func brightnessMap(from entry: Entry) -> [LightingCondition: Double] {
        var brightness: [LightingCondition: Double] = [:]
        for (key, value) in entry.channels {
            if let condition = LightingCondition(rawValue: key) {
                brightness[condition] = value
            }
        }
        return brightness
    }

    private static func targetVector(from entry: Entry) -> TargetResponseVector {
        TargetResponseVector(brightnessMap(from: entry))
    }

    private static func paletteColors(from scenario: Scenario) throws -> [PaletteColor] {
        try scenario.palette
            .sorted { ($0.index ?? 0) < ($1.index ?? 0) }
            .map { entry in
                guard let rgb = RGBColor(hex: entry.hexColor) else {
                    throw ParityHarnessError.invalidHex(entry.hexColor)
                }
                var responses: [LightingCondition: IlluminationResponse] = [:]
                for (key, value) in entry.channels {
                    if let condition = LightingCondition(rawValue: key) {
                        responses[condition] = IlluminationResponse(brightness: value)
                    }
                }
                return PaletteColor(
                    id: entry.index ?? 0,
                    hex: entry.hexColor,
                    rgb: rgb,
                    responses: responses
                )
            }
    }
}
